import { number } from '@storybook/addon-knobs';
import React from 'react';

import { Axis, BarSeries, Chart, Position, ScaleType, Settings } from '@elastic/charts';

import type { ChartsStory } from '../../types';
import { useBaseTheme } from '../../use_base_theme';
import { customKnobs } from '../utils/knobs';

export const Example: ChartsStory = (_, { title, description }) => {
  const minBarHeight = number('minBarHeight', 5);
  const yScaleType = customKnobs.enum.scaleType(undefined, 'linear', {
    include: ['LinearBinary', 'Linear', 'Time', 'Log', 'Sqrt'],
  });
  const data = [
    [1, 100000],
    [2, 10000],
    [3, 1000],
    [4, 100],
    [5, 10],
    [6, 1],
    [7, 0],
    [8, 1],
    [9, 0],
  ];
  return (
    <Chart title={title} description={description}>
      <Settings baseTheme={useBaseTheme()} />
      <Axis id="bottom" title="Bottom" position={Position.Bottom} />
      <Axis id="left" title="Left" position={Position.Left} />
      <BarSeries
        id="bars"
        xScaleType={ScaleType.Linear}
        yScaleType={yScaleType}
        xAccessor={0}
        yAccessors={[1]}
        data={data}
        minBarHeight={minBarHeight}
      />
    </Chart>
  );
};



