import React from 'react';

import type { SeriesNameConfigOptions } from '@elastic/charts';
import { Axis, BarSeries, Chart, Position, ScaleType, Settings, LegendValue } from '@elastic/charts';
import * as TestDatasets from '@elastic/charts/src/utils/data_samples/test_dataset';

import type { ChartsStory } from '../../types';
import { useBaseTheme } from '../../use_base_theme';

export const Example: ChartsStory = (_, { title, description }) => {
  const customSeriesNameOptions: SeriesNameConfigOptions = {
    names: [
      {
        // replace split accessor;
        accessor: 'g',
        value: 'a',
        name: 'replace a(from g)',
      },
      {
        // replace y accessor;
        accessor: 'y2',
        name: 'replace y2',
      },
    ],
    delimiter: ' | ',
  };
  return (
    <Chart title={title} description={description}>
      <Settings
        showLegend
        legendValues={[LegendValue.CurrentAndLastValue]}
        legendPosition={Position.Right}
        baseTheme={useBaseTheme()}
      />
      <Axis id="bottom" position={Position.Bottom} title="Bottom axis" showOverlappingTicks />
      <Axis id="left2" title="Left axis" position={Position.Left} tickFormat={(d: any) => Number(d).toFixed(2)} />

      <BarSeries
        id="bars1"
        xScaleType={ScaleType.Ordinal}
        yScaleType={ScaleType.Linear}
        xAccessor="x"
        yAccessors={['y1', 'y2']}
        splitSeriesAccessors={['g']}
        data={TestDatasets.BARCHART_2Y1G}
        name={customSeriesNameOptions}
      />
    </Chart>
  );
};



