import type { ComponentProps, ComponentType, CSSProperties, ReactElement, ReactNode } from 'react';
import type { $Values } from 'utility-types';

import { ChartType } from '../..';
import type { Color } from '../../../common/colors';
import type { MeterFill, MeterSize } from '../../../components/meter';
import type { Spec } from '../../../specs/spec_type';
import { SpecType } from '../../../specs/spec_type'; // kept as long-winded import on separate line otherwise import circularity emerges
import { specComponentFactory } from '../../../state/spec_factory';
import type { LayoutDirection, ValueFormatter } from '../../../utils/common';
import type { GenericDomain } from '../../../utils/domain';
import type { BulletValueLabels } from '../../bullet_graph/spec';

/**
 * Props for displaying a secondary metric value with optional label and badge styling.
 *
 * @alpha
 * */
export interface SecondaryMetricProps {
  /** The main value to display */
  value: string;
  /** Optional label to display alongside the value */
  label?: string;
  /** Optional background color for the value badge. If not provided, no badge is displayed */
  badgeColor?: Color;
  /** Optional text color for the value badge. If not provided, it will be computed automatically for contrast */
  badgeTextColor?: Color;
  /** Determines whether the label appears before or after the value */
  labelPosition?: 'before' | 'after';
  /**  Optional CSS properties to apply to the container element */
  style?: CSSProperties;
  /** Optional aria description */
  ariaDescription?: string;
  /** Badge border config:
   * - undefined: no border
   * - `{ mode: 'none' }`: explicitly disable border
   * - `{ mode: 'auto' }`: parent computes a white or black border based on contrast with the badge and metric background colors
   * - `{ mode: 'custom', color: Color }`: use provided color
   */
  badgeBorderColor?: { mode: 'none' } | { mode: 'auto' } | { mode: 'custom'; color: Color };
  /** Optional icon displayed next to the text */
  icon?: string;
  /** Determines whether the icon appears before or after the value */
  iconPosition?: 'before' | 'after';
}

/** @alpha */
export type MetricBase = {
  color: Color;
  /**
   * Overrides background color from `Theme.background` and `Theme.metric.emptyBackground`
   */
  background?: Color;
  title?: string;
  valueColor?: Color;
  valueIcon?: ComponentType<{ width: number; height: number; color: Color; verticalAlign: 'middle' }>;
  subtitle?: string;
  /**
   * Optional extra content to display below the subtitle.
   * - Can be a React element, a component type (which will receive `fontSize` and `color` props), or a SecondaryMetricProps object.
   * - If a SecondaryMetricProps object is provided, it will be rendered using the SecondaryMetric component.
   */
  extra?: ReactElement | ComponentType<{ fontSize: number; color: string }> | SecondaryMetricProps;
  icon?: ComponentType<{ width: number; height: number; color: Color }>;
  body?: ReactNode;
};

/** @alpha */
export type MetricWText = MetricBase & {
  value: string;
  valueFormatter?: never;
};

/** @alpha */
export type MetricWNumberArrayValues = MetricBase & {
  value: Array<number>;
  valueFormatter: ValueFormatter<number>;
};

/** @alpha */
export type MetricWStringArrayValues = MetricBase & {
  value: Array<string>;
  valueFormatter?: never;
};

/** @alpha */
export type MetricWNumber = MetricBase & {
  value: number;
  target?: number;
  valueFormatter: ValueFormatter;
  /**
   * Used for header display only, defaults to `valueFormatter`
   */
  targetFormatter?: ValueFormatter;
};

/**
 * Accessible labels used by explicit-domain Metric progress bars.
 *
 * When `MetricWProgress.domain` is provided, Metric exposes actual values rather
 * than derived percentages for titles and aria text. These labels customize that
 * value and target wording.
 *
 * @alpha
 */
export interface MetricProgressValueLabels {
  value: string;
  target: string;
}

/** @alpha */
export type MetricWProgress = MetricWNumber & {
  progressBarDirection: LayoutDirection;
  /**
   * Optional Meter fill configuration for the progress bar.
   *
   * Colors are resolved against the Metric tile background before rendering.
   * Defaults to a single-color fill derived from `color`.
   */
  progressBarFill?: MeterFill;
  /**
   * Optional Meter thickness preset for the progress bar.
   * Use this when a parent layout, such as Lens table row density, needs to map
   * onto a fixed progress bar thickness. When omitted, the bar size is derived
   * from the Metric tile layout.
   */
  progressBarSize?: MeterSize;
  /**
   * Maximum value of the Metric progress domain.
   */
  domainMax: number;
  /**
   * Optional minimum value of the Metric progress domain.
   * Defaults to `0`, preserving the existing zero-based Metric behavior.
   * Set this when Metric should render a signed or custom range.
   */
  domainMin?: number;
  /**
   * Optional labels for explicit-domain value and target text.
   * Defaults to `Value` and `Target`.
   * Ignored when `domainMin` is omitted.
   */
  progressValueLabels?: MetricProgressValueLabels;
};

/** @internal Type used by Bullet chart Metric rendering. */
export type BulletMetricWProgress = MetricWNumber & {
  progressBarDirection: LayoutDirection;
  progressBarFill?: MeterFill;
  progressBarSize?: MeterSize;
  domain: GenericDomain;
  /** Preserve Bullet's tick-domain nicing behavior in the shared Metric progress adapter. */
  niceDomain?: boolean;
  /**
   * Bullet uses value/target wording that is owned by the Bullet chart contract.
   */
  valueLabels: Omit<BulletValueLabels, 'active'>;
};

/** @alpha */
export const MetricTrendShape = Object.freeze({
  Bars: 'bars' as const,
  Area: 'area' as const,
});

/** @alpha */
export type MetricTrendShape = $Values<typeof MetricTrendShape>;

/** @alpha */
export type MetricWTrend = (MetricWNumber | MetricWText | MetricWNumberArrayValues | MetricWStringArrayValues) & {
  trend: { x: number; y: number }[];
  trendShape: MetricTrendShape;
  trendA11yTitle?: string;
  trendA11yDescription?: string;
};

/** @alpha */
export type MetricDatum =
  | MetricWNumber
  | MetricWText
  | MetricWNumberArrayValues
  | MetricWStringArrayValues
  | MetricWProgress
  | MetricWTrend;

/** @alpha */
export interface MetricSpec extends Spec {
  specType: typeof SpecType.Series;
  chartType: typeof ChartType.Metric;
  data: (MetricDatum | undefined)[][];
}

/** @alpha */
export const Metric = specComponentFactory<MetricSpec>()(
  {
    chartType: ChartType.Metric,
    specType: SpecType.Series,
  },
  {
    data: [],
  },
);

// TODO: Remove this for overall spec prop consistency as this does not refer to the spec props but the metric component props that are defined by the spec
/**
 * @deprecated in favor of MetricProps
 * @alpha
 */
export type MetricSpecProps = ComponentProps<typeof Metric>;

/**@alpha */
export type MetricProps = ComponentProps<typeof Metric>;

/** @internal */
export function isBulletMetric(datum: MetricDatum): datum is BulletMetricWProgress {
  return (
    isMetricWNumber(datum) &&
    Array.isArray((datum as BulletMetricWProgress).domain) &&
    datum.hasOwnProperty('valueLabels')
  );
}

/** @internal */
export function isMetricWNumberArrayValues(datum: MetricDatum): datum is MetricWNumberArrayValues {
  return Array.isArray(datum.value) && typeof datum.value[0] === 'number' && datum.hasOwnProperty('valueFormatter');
}

/** @internal */
export function isMetricWStringArrayValues(datum: MetricDatum): datum is MetricWStringArrayValues {
  return Array.isArray(datum.value) && typeof datum.value[0] === 'string';
}

/** @internal */
export function isMetricWNumber(datum: MetricDatum): datum is MetricWNumber {
  return 'value' in datum && typeof datum.value === 'number' && datum.hasOwnProperty('valueFormatter');
}

/** @internal */
export function isMetricWText(datum: MetricDatum): datum is MetricWText {
  return 'value' in datum && typeof datum.value === 'string';
}

/** @internal */
export function isMetricWProgress(datum: MetricDatum): datum is MetricWProgress {
  return isMetricWNumber(datum) && !datum.hasOwnProperty('trend') && datum.hasOwnProperty('domainMax');
}

/** @internal */
export function isMetricWTrend(datum: MetricDatum): datum is MetricWTrend {
  return (
    (isMetricWNumber(datum) ||
      isMetricWText(datum) ||
      isMetricWNumberArrayValues(datum) ||
      isMetricWStringArrayValues(datum)) &&
    datum.hasOwnProperty('trend') &&
    !datum.hasOwnProperty('domainMax')
  );
}

/** @internal */
export const isSecondaryMetricProps = (props: any): props is SecondaryMetricProps => {
  return (
    props &&
    'value' in props &&
    typeof props.value === 'string' &&
    (props.label === undefined || typeof props.label === 'string') &&
    (props.badgeColor === undefined || typeof props.badgeColor === 'string') &&
    (props.badgeTextColor === undefined || typeof props.badgeTextColor === 'string')
  );
};
