import { number } from '@storybook/addon-knobs';
import React from 'react';

import { AreaSeries, Axis, Chart, Position, ScaleType, Settings, timeFormatter } from '@elastic/charts';
import { KIBANA_METRICS } from '@elastic/charts/src/utils/data_samples/test_dataset_kibana';

import type { ChartsStory } from '../../types';
import { useBaseTheme } from '../../use_base_theme';
import { customKnobs } from '../utils/knobs';

const dateFormatter = timeFormatter('HH:mm');

const data = KIBANA_METRICS.metrics.kibana_os_load.v1.data.map(([x, y]) => [x, -y]);

export const Example: ChartsStory = (_, { title, description }) => {
  const yScaleType = customKnobs.enum.scaleType('Y scale', ScaleType.Linear, { include: ['Linear', 'Log'] });

  return (
    <Chart title={title} description={description}>
      <Settings baseTheme={useBaseTheme()} />
      <Axis id="bottom" position={Position.Bottom} showOverlappingTicks tickFormat={dateFormatter} />
      <Axis
        id="left"
        title="negative metric"
        position={Position.Left}
        tickFormat={(d) => Number(d).toFixed(2)}
        domain={{
          min: NaN,
          max: NaN,
          logMinLimit: number('Y log limit', 1, { min: 0 }),
        }}
      />

      <AreaSeries
        id="area"
        xScaleType={ScaleType.Time}
        yScaleType={yScaleType}
        xAccessor={0}
        yAccessors={[1]}
        data={data}
      />
    </Chart>
  );
};



Example.parameters = { storySource: { source: "(_, { title, description }) => {\n  const yScaleType = customKnobs.enum.scaleType('Y scale', ScaleType.Linear, { include: ['Linear', 'Log'] });\n\n  return (\n    <Chart title={title} description={description}>\n      <Settings baseTheme={useBaseTheme()} />\n      <Axis id=\"bottom\" position={Position.Bottom} showOverlappingTicks tickFormat={dateFormatter} />\n      <Axis\n        id=\"left\"\n        title=\"negative metric\"\n        position={Position.Left}\n        tickFormat={(d) => Number(d).toFixed(2)}\n        domain={{\n          min: NaN,\n          max: NaN,\n          logMinLimit: number('Y log limit', 1, { min: 0 }),\n        }}\n      />\n\n      <AreaSeries\n        id=\"area\"\n        xScaleType={ScaleType.Time}\n        yScaleType={yScaleType}\n        xAccessor={0}\n        yAccessors={[1]}\n        data={data}\n      />\n    </Chart>\n  );\n}" }, ...Example.parameters };